insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 1, 'Why is an anti-collision scan a permit-to-drill item?', '["Because regulators require documentation.", "Because an intersected wellbore can flow, and the standard outcome is losing both wells.", "Because the scan takes long enough that it has to be scheduled before the rig arrives on the location.", "Because the offset well''s operator has to consent to the plan before their data can be used in the calculation."]'::jsonb, 1, 'If the offset is a producer, its pressure is in your annulus with no barrier. If it is an injector, you have an unplanned high-rate connection.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 2, 'Which case runs the same mathematics in reverse?', '["A relief well, where the object is to intersect deliberately.", "A sidetrack from an existing hole.", "An infill well in a mature field, where the offsets were drilled with tools whose error models no longer exist.", "A shallow hazard scan, where the object is not another well but a pipeline or a conductor stub."]'::jsonb, 0, 'Everything else in the course is about staying away. Ranging toward a target well uses the same geometry and is not certified here.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 3, 'Why is scanning station to station wrong?', '["Because the stations are not synchronised.", "Because the offset well''s stations were surveyed with a different tool, so its positions are not directly comparable.", "Because the true closest point is generally between two offset stations.", "Because the reference well''s stations are at different measured depths from the offset''s, so no pairing exists."]'::jsonb, 2, 'It overestimates the separation, and on a thirty metre interval with two wells crossing at an angle the overestimate can be metres.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 4, 'What does the engine solve at each reference station?', '["The distance to the nearest offset station.", "The intersection of the two well paths, if one exists, and otherwise the midpoint of the shortest connecting segment.", "The measured depth on the reference well at which the offset well is closest, which is then interpolated.", "The closest point on the offset well''s path, treated as a sequence of arcs."]'::jsonb, 3, 'It does it in closed form, for a point and an arc whose unit tangents rotate over a measured-depth span.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 5, 'Why does the closest-approach solution need to be closed form?', '["Because a scan over two long wells is tens of thousands of evaluations.", "Because iteration would not converge.", "Because an iterative search would give a different answer at each run, which is unacceptable for a permit item.", "Because the arcs are not differentiable at their joins, which prevents any gradient-based search from working."]'::jsonb, 0, 'An iterative search at each one would be slow enough to stop a planner from adjusting a trajectory interactively.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 6, 'What does a straight interval reduce to in the closest-approach routine?', '["A special case that is skipped.", "Projecting the point onto the tangent line.", "An arc of very large radius, which the routine handles by clamping the dogleg to a small positive threshold value.", "A comparison of the two endpoints, since the minimum on a straight segment always occurs at one of its ends."]'::jsonb, 1, 'It is the degenerate case the same routine handles, which is why a zero-dogleg guard belongs there just as it does in the survey calculation.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 7, 'What three things come off the centre-to-centre distance before uncertainty is considered?', '["Two hole radii and the surface position sigma.", "The reference hole radius, the tool projection allowance, and the combined sigma projected onto the connecting line.", "The two hole radii and a tool projection allowance.", "The two hole radii and the survey interval, which bounds how far the true closest approach can be from a station."]'::jsonb, 2, 'What is left is the separation between the two wellbore SURFACES, with an allowance, and that is what the uncertainty is compared against.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 8, 'In the standard clearance example, how much of the gap is spoken for by geometry alone?', '["Half a metre, the surface position term.", "It depends on the hole sizes actually drilled, so no fixed figure applies to the standard example at all.", "Nothing, because the radii and the allowance are applied to the uncertainty rather than to the distance.", "About 1.062 m, from a 0.4572 m radius, a 0.3048 m radius, and a 0.3 m allowance."]'::jsonb, 3, 'For two wells a few metres apart near surface, over a metre of the gap is gone before anything uncertain is considered.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 9, 'Why are the hole radii inputs rather than constants?', '["Because a reamed or washed-out hole is larger than the bit that drilled it.", "Because the standard leaves them undefined.", "Because the radius varies along the well, so a single value has to be chosen for each section by the planner.", "Because different operators use different conventions for whether the radius is the bit size or the casing size."]'::jsonb, 0, 'The standard examples use values corresponding to a thirty-six inch and a twenty-four inch hole, which are section sizes rather than universal constants.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 10, 'What is the commonest reason an anti-collision scan is wrong?', '["The closest approach solver failed.", "The two wells are not expressed in one coordinate frame.", "The offset well''s error model parameters are unknown, so its uncertainty had to be assumed rather than computed.", "The confidence factor used for the scan differed from the one the operator''s procedure specifies."]'::jsonb, 1, 'The calculation then runs perfectly and answers a question about two wells that are not where it thinks they are.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 11, 'Two wells'' surveys are each stored relative to their own wellhead. What happens if the offsets are not applied?', '["They are placed at random positions.", "Nothing, because the separation factor depends only on the relative geometry and not on the common origin.", "They are placed at the same surface point, which makes them look far too close.", "The deeper well is shifted vertically relative to the shallower one by the difference in their rig floor elevations."]'::jsonb, 2, 'That error at least gets noticed. Applying an offset that was already applied makes them look far apart, and that one does not.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 12, 'One well''s azimuths are grid-referenced and the other''s true. What is the size of the error?', '["The declination, typically a few degrees.", "Negligible, since convergence is under one degree in every standard map projection used in the industry.", "It depends on the depth datum as well, because the two effects combine into a single three-dimensional offset.", "The convergence, which on a well 3000 m out is 52 m per degree."]'::jsonb, 3, 'The standard clearance example uses grid north with zero convergence, which removes the issue from the example and not from real fields.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 13, 'A jack-up well and a platform well at the same location are compared. What must be checked?', '["Their depth datums, since the rig floor elevations differ.", "Their hole radii.", "Their magnetic headers, since the two rigs were on location at different dates and the declination will have drifted.", "Their survey intervals, since a scan compares stations and the two lists must be sampled at the same depths."]'::jsonb, 0, 'A scan that compares them without correcting has one well systematically shifted in the vertical direction.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 14, 'Why does the standard clearance golden supply positions rather than only attitudes?', '["Because attitudes are not published.", "So that every well is unambiguously in one shared frame.", "Because the positions allow the closest approach to be found without running the survey calculation at all.", "Because the error model needs positions as input, and recomputing them from attitudes would introduce a difference."]'::jsonb, 1, 'It removes the frame question from the validation, which is the one part of the problem a published test cannot check for you.'),
  ('welldesign', 'advanced', 'module', 'm01-two-wells-in-one-frame', 15, 'What produces no warning at all in an anti-collision scan?', '["A separation factor below 1.0.", "A well whose survey has a gross error, since the model describes the spread of correct measurements only.", "An offset well that was not in the list of offsets.", "An offset well whose parameter set is unknown, since the calculation cannot proceed without one."]'::jsonb, 2, 'Old wells, plugged wells, sidetracks recorded as one entity, another operator''s wells, and shallow hazards that are not wells.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 1, 'What is the numerator of the separation factor?', '["The centre-to-centre distance alone.", "Centre-to-centre distance less both hole radii and the tool projection allowance.", "The centre-to-centre distance less the combined uncertainty of the two wells at the chosen confidence factor.", "The distance between the two wellbore surfaces at their closest approach, before the tool allowance is applied."]'::jsonb, 1, 'It is the geometric clearance. Every term in it follows from the two surveys and the two hole sizes, and none of it is uncertain.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 2, 'What is the denominator?', '["The combined uncertainty projected onto the line between the wells, times k.", "The sum of the two hole radii.", "The larger of the two wells'' semi-major axes at the chosen confidence, since the combination is dominated by it.", "The uncertainty of the reference well alone, since the offset''s position is treated as known in the standard method."]'::jsonb, 0, 'It includes the surface position term, which the survey error model does not carry, added as a separate contribution.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 3, 'Why is the separation factor dimensionless?', '["Because k is dimensionless.", "Because both the clearance and the uncertainty are normalised by the centre-to-centre distance before dividing.", "Because it is a length divided by a length.", "Because it is a probability, and probabilities carry no units by construction."]'::jsonb, 2, 'That is why one threshold works across hole sizes, depths, and tools: the number already carries the scale of the problem.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 4, 'What is the pedal radius of an ellipse in a given direction?', '["The radius along that direction.", "The distance from the centre to the point on the ellipse whose outward normal points along that direction.", "The projection of the semi-major axis onto that direction, weighted by the cosine of the angle between them.", "The distance from the centre to the tangent line perpendicular to that direction."]'::jsonb, 3, 'The radial distance is what most people picture, and it is not what a separation calculation needs.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 5, 'Why is the pedal radius the right one for clearance?', '["Because the question is how far the ellipse can extend TOWARDS the other well.", "Because it is always smaller.", "Because it is the only definition that is invariant under a rotation of the coordinate frame the ellipse is expressed in.", "Because the standard defines it that way and consistency between implementations matters more than the choice."]'::jsonb, 0, 'For a tilted elongated ellipse the two answers differ, and the difference is in the unsafe direction if you take the radial one.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 6, 'What does the standard clearance set contain?', '["A single pair of crossing wells.", "One reference well and eleven offsets, with published per-station separation factors.", "Eleven reference wells, each with one offset, chosen to cover the range of geometries a real field presents.", "One reference well and eleven offsets, with published minimum separation factors but no per-station values."]'::jsonb, 1, 'Every well comes with its survey, its positions in a shared frame, and its own magnetic header.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 7, 'Why eleven cases rather than one?', '["Because the standard requires eleven.", "Because eleven is the number of distinct offset well geometries that occur on a typical platform template.", "Because an implementation can be right in one geometry and wrong in another.", "Because a statistical comparison needs enough cases to estimate the spread of the implementation''s error."]'::jsonb, 2, 'Parallel wells exercise the along-hole terms, crossing wells the closest-approach solver, close-at-surface wells the surface term, and the kicked-off case the shared-uncertainty logic.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 8, 'What are the fixed parameters of the standard clearance set?', '["Only the confidence factor, k 3.5.", "The confidence factor and the two hole radii; the surface term and the allowance are chosen by the implementer.", "The error model revision and the parameter set, from which all the other values follow by the standard''s defaults.", "Pedal curve, k 3.5, surface sigma 0.5 m, allowance 0.3 m, radii 0.4572 and 0.3048 m."]'::jsonb, 3, 'Every one of them changes the answer, which is why a published case has to fix all of them rather than only the interesting ones.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 9, 'What is the industry no-go threshold?', '["1.0, below which the uncertainty envelopes overlap at the chosen confidence.", "1.5, the review threshold.", "3.5, the confidence factor, since a factor below its own k means the wells are within one standard deviation.", "Zero, since a positive separation factor means the wells do not overlap at any confidence."]'::jsonb, 0, 'A factor of exactly 1 means the ellipses touch at k of 3.5. That sounds like a wide margin and it is not.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 10, 'Why is the action threshold set at 1.5 rather than 1.0?', '["Because 1.5 is half again as safe.", "Because the model excludes gross errors, old wells'' real parameter sets, and its own tails.", "Because the confidence factor of 3.5 corresponds to 99.8 percent in two dimensions and to rather less in three.", "Because the separation factor is computed at stations and the true minimum lies between them."]'::jsonb, 1, 'k of 3.5 is not a calculated risk level; it is an agreed scaling of a model that is itself approximate.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 11, 'What happens between 1.0 and 1.5?', '["The well is drilled as planned.", "The plan is rejected outright, since only factors above the review threshold are considered acceptable.", "The well goes to review: mitigation, a revised plan, or an explicit management decision.", "The confidence factor is reduced until the factor rises above 1.5, which is the documented remedy."]'::jsonb, 2, 'Adjusting k afterwards to clear a threshold is exactly what module 3 says must not happen.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 12, 'Across the eleven cases, what does the engine reproduce?', '["It reproduces the minima only.", "It reproduces ten of the eleven; the kicked-off case differs on its minimum and is excluded from the comparison.", "It agrees to about one percent on all eleven, which is the tolerance the standard states for a conforming implementation.", "All eleven minimum separation factors reproduced, ten of them at machine precision throughout."]'::jsonb, 3, 'The eleventh, the kicked-off case, agrees exactly on its minimum and differs at far-field stations where the factor is above twenty.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 13, 'How can a separation factor be negative?', '["Because the geometric clearance in the numerator can itself go negative.", "Because k can be chosen negative.", "Because the combined uncertainty exceeds the centre-to-centre distance, which flips the sign of the whole ratio.", "It cannot: the implementation clamps the factor at zero and reports an overlap flag instead."]'::jsonb, 0, 'When the two hole radii and the allowance exceed the centre-to-centre distance, the numerator is negative and so is the factor.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 14, 'What does a negative separation factor mean physically?', '["They are closer than the review threshold.", "The two wells, at the chosen confidence, might be in the same place.", "The reference well passes within one hole radius of the offset, which is the definition of a grazing contact.", "The calculation has been run with the wells in different frames, which is the only way the numerator can go negative."]'::jsonb, 1, 'Not close: overlapping. It is an absolute no-go and no amount of monitoring makes it acceptable.'),
  ('welldesign', 'advanced', 'module', 'm02-the-separation-factor', 15, 'Why does the separation factor scale break below zero?', '["Because the logarithm is undefined.", "Because the pedal radius is undefined when the two ellipses overlap, so the denominator loses its meaning.", "Because increasing the uncertainty then moves the number towards zero, which reads as an improvement.", "Because the thresholds of 1.0 and 1.5 were calibrated on positive factors and have no negative counterparts."]'::jsonb, 2, 'For a positive factor, doubling the clearance doubles the number. For a negative one, the numerator is fixed and only the denominator moves.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 1, 'How does a positive separation factor vary with the confidence factor?', '["It is independent of k.", "It falls as the square of k, since the confidence factor scales both semi-axes of each well''s ellipse.", "Inversely: halve k and the factor doubles.", "It varies with k only through the pedal radius, which depends on the ellipse shape as well as its scale."]'::jsonb, 2, 'That is the whole of its effect, and it is a large one. It is also why k has to be agreed in advance rather than adjusted afterwards.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 2, 'What is the industry convention for k in anti-collision?', '["3.5.", "1.96, the two-sided ninety-five percent value.", "2.7955, which is the two-dimensional ninety-five percent factor used for reporting position ellipses.", "It is set per operator, with values between 2 and 5 in common use across the industry."]'::jsonb, 0, 'In two dimensions it corresponds to about 99.8 percent under a normal assumption, and rather less in three, and that translation is not really the point.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 3, 'Why is 3.5 not really a probability statement?', '["Because probabilities cannot exceed one.", "Because it scales a model with unmodelled tails, so it carries a risk judgement instead.", "Because the underlying distribution is not normal, so no confidence factor corresponds to a stated probability at all.", "Because the factor is applied to the combined uncertainty rather than to each well''s ellipse separately."]'::jsonb, 1, 'Gross errors, surface position, hole radius, and model error all sit outside the covariance that k is scaling.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 4, 'What term does the clearance calculation add that the survey model does not carry?', '["The tool projection allowance only.", "The declination uncertainty, which is global and therefore common to both wells rather than accumulated by either.", "The hole radius, which the survey model treats as zero because it describes a centreline.", "The surface position uncertainty of the wellhead itself."]'::jsonb, 3, 'The radius is also added and it is a geometric deduction rather than an uncertainty. The survey model starts at the tie-on and says nothing about where the tie-on is.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 5, 'What value do the standard clearance examples use for surface position sigma?', '["0.5 m at one sigma.", "0.3 m, the same as the tool allowance.", "It is derived per well from the survey model, using the depth reference source evaluated at zero measured depth.", "0.4572 m, matching the reference well''s hole radius, since both describe the same physical extent at surface."]'::jsonb, 0, 'For a modern satellite-positioned wellhead that is generous. For an old well positioned by triangulation from a shoreline it is optimistic by an order of magnitude.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 6, 'Why does the surface term dominate the shallow section?', '["Because the wells are vertical there.", "Because the survey uncertainty starts at zero and grows, while the surface term is there from the first metre.", "Because the shallow section is drilled without a magnetic survey tool, so no survey uncertainty exists at all.", "Because the depth-only sources have not yet accumulated, and they are what the survey uncertainty consists of."]'::jsonb, 1, 'At a hundred metres below the mudline a well''s own survey uncertainty is centimetres against half a metre of surface term.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 7, 'Where on a platform is the anti-collision problem hardest?', '["At total depth, where the ellipses are largest.", "At the kickoff, where the trajectories first diverge and the shared uncertainty stops being shared.", "In the shallow section, where slots are metres apart and the wells are nudging away from each other.", "Wherever two wells cross, since a crossing produces a sharp minimum that the station spacing may miss."]'::jsonb, 2, 'That is exactly where the survey model contributes almost nothing, and every decision is about wellhead positions instead.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 8, 'What does the tool projection allowance cover?', '["The uncertainty of the last survey station.", "The distance between the bit and the first stabiliser, which sets how far the assembly can deviate before it is measured.", "The extra hole drilled between the last survey and the next connection, which is unsurveyed by definition.", "The hole ahead of the sensor, and the string lying off the hole centreline."]'::jsonb, 3, 'The sensor sits ten to twenty metres behind the bit, and the string lies against the low side, is pushed by a bent housing, and buckles under compression.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 9, 'How large is the allowance in the published clearance set?', '["0.3 m.", "0.5 m, the same as the surface term.", "It is computed per section from the assembly length between the bit and the sensor package in the collar.", "0.4572 m, which corresponds to the clearance between a thirty-six inch hole and the drill pipe inside it."]'::jsonb, 0, 'That is small next to the uncertainties in a deep well and comparable to everything else in a shallow one.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 10, 'Is the tool projection allowance a safety margin?', '["Yes, it is the margin above the no-go line.", "No: it is a geometric correction for where the steel actually is.", "Yes, it is the industry''s allowance for the difference between a plan and the hole that gets drilled from it.", "No, it is a statistical term, added in quadrature with the two wells'' position uncertainties."]'::jsonb, 1, 'It is subtracted from the distance rather than added to the uncertainty, which is what makes it geometry rather than statistics.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 11, 'Two wells from the same slot share part of their uncertainty. Why does that matter?', '["Because it doubles the combined sigma.", "Because the two wells'' covariances are then singular, and the pedal radius cannot be computed from a singular matrix.", "Because shared error does not affect their relative position at all.", "Because the standard requires shared uncertainty to be excluded from any clearance calculation between sidetracks."]'::jsonb, 2, 'If the wellhead is forty centimetres north of where the database says, both wells are, and the gap between them is unchanged.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 12, 'What does treating shared uncertainty as independent do?', '["It makes the wells look further apart.", "It has no effect on the minimum separation factor, only on the far-field stations where the wells have diverged.", "It produces a negative separation factor, since the doubled uncertainty exceeds the geometric clearance.", "It inflates the combined sigma, so the wells look closer than they are."]'::jsonb, 3, 'A plan that is actually safe is rejected. Pessimistic rather than dangerous, and still wrong.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 13, 'For a sidetrack, down to what depth is the sharing exact?', '["The kickoff point, above which the two wells are the same hole.", "The last casing shoe.", "The tie-on depth of the sidetrack''s own survey, which is where its independent error accumulation begins.", "The surface, since only the wellhead position is genuinely common to the two wells."]'::jsonb, 0, 'Above the kickoff there is one hole with one survey, so there is nothing for the two wells to disagree about.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 14, 'The sensitivity view runs a pair at k of 2.0, 3.5 and 5.0. What is it demonstrating?', '["That the geometry is stable under k.", "That the answer moves a long way on a number that was chosen rather than measured.", "That the pedal-curve method and the radial method converge as the confidence factor is increased.", "That the no-go threshold of 1.0 corresponds to a different physical clearance at each confidence factor."]'::jsonb, 1, 'The threshold point is real and it is a consequence of the same fact. The demonstration is that k is a lever, not a measurement.'),
  ('welldesign', 'advanced', 'module', 'm03-what-it-moves-with', 15, 'What is the correct handling of k when a plan is close to the threshold?', '["Raise it until the plan clears.", "Lower it, since a lower confidence factor is conservative for a negative separation factor and the plan may be unsafe.", "Agree it in advance and leave it alone.", "Report the factor at all three of 2.0, 3.5 and 5.0 and let the reviewer choose which one to act on."]'::jsonb, 2, 'Adjusting the confidence factor after seeing the answer converts a safety criterion into a formality.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 1, 'What is magnetic north?', '["The direction of the magnetic pole.", "The direction of the horizontal component of the earth''s field where the tool is.", "The direction a compass points after it has been corrected for the local declination and grid convergence.", "The axis of the earth''s dipole field, which is tilted about eleven degrees from the rotational axis."]'::jsonb, 1, 'It is what a magnetometer measures, and it moves both year to year and hour to hour.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 2, 'Which direction does a map projection''s northing axis define?', '["The direction of the northing axis of the map projection the field uses.", "The direction of the geographic pole.", "The direction of the survey grid the operator has defined for the field, which is arbitrary and set by convention.", "True north corrected for declination, which is what a grid-referenced survey listing reports."]'::jsonb, 0, 'It equals true north only on the projection''s central meridian, and the angle between them is the convergence.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 3, 'Which of the two angles depends on time?', '["Convergence, because projections are revised.", "Both, since the geodetic datum a projection is built on is itself updated as plate motion is measured.", "Declination, because the earth''s field changes.", "Neither: both are fixed properties of the location once the projection has been chosen."]'::jsonb, 2, 'Convergence depends only on position and on the projection. Declination is physics with a date on it.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 4, 'Which way do the two conversions go?', '["Both are additions to the magnetic azimuth.", "True is magnetic less declination, and grid is true plus convergence, with both angles positive west.", "Magnetic is grid plus declination less convergence, which is the single conversion the header records.", "True is magnetic plus declination, and grid is true less convergence."]'::jsonb, 3, 'Both signs are conventions and both have been implemented backwards in real software. The check is a case with a known answer.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 5, 'What is the world magnetic model?', '["A spherical harmonic expansion of the earth''s main field, with a secular variation term.", "A global database of observatory readings.", "A grid of declination values interpolated between magnetic observatories, updated annually by the two agencies.", "A model of the field including the crustal and ionospheric contributions, which the survey correction requires."]'::jsonb, 0, 'It is produced jointly by the American and British geological agencies and released every five years, valid for that period.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 6, 'Which three of its outputs does a survey system need?', '["The three field components in the tool frame.", "Declination for the azimuth correction, total field and dip for the error model.", "Declination, inclination, and the horizontal component, from which the total field is obtained by trigonometry.", "The total field, the secular variation rate, and the model''s stated uncertainty at the location and date."]'::jsonb, 1, 'The error model''s refusal to run without total field and dip is the same requirement, seen from the other side.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 7, 'What is the model''s own stated uncertainty in declination?', '["A few thousandths of a degree.", "About two degrees, which is why in-field referencing is mandatory for any critical anti-collision section.", "Around half a degree at mid latitudes, larger near the poles.", "It is not stated, because the uncertainty depends on the crustal field, which the model does not attempt to represent."]'::jsonb, 2, 'Half a degree at 3000 m of displacement is 26 m, which is why the error model carries declination sources at all.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 8, 'Why does the model degrade through its five-year validity?', '["Because the coefficients are rounded.", "Because the number of contributing observatories falls over the period as older stations are decommissioned.", "Because the crustal field, which the model omits, grows in relative importance as the main field weakens.", "Because the secular variation term is linear and reality is not."]'::jsonb, 3, 'That is why the release cycle is five years and why the evaluation date is part of the input rather than an afterthought.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 9, 'Two wells at the same location were drilled ten years apart. What differs in their headers?', '["Their declinations, because the field drifted between the two dates.", "Their grid convergences.", "Their total field strengths only, since declination is a property of the location rather than of the date.", "Nothing, provided both were referenced to true north, which removes the magnetic dependence from the listing."]'::jsonb, 0, 'For a well 3000 m out, the drift over a decade can be tens of metres of position if the old survey is recomputed with today''s value.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 10, 'Should an old well''s survey be recomputed with today''s declination?', '["Yes, always, for consistency.", "Neither choice is obviously right; what matters is knowing which was done.", "No, never: a survey must always be preserved with the correction that was applied when it was taken.", "Only if the well is an offset in an anti-collision scan, where both wells must share a single reference epoch."]'::jsonb, 1, 'Recomputing rotates it by the drift. Leaving it makes it consistent with the field as it was. The header''s declination and date are the record.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 11, 'What is the approximate formula for grid convergence?', '["The latitude times the declination.", "The longitude difference from the central meridian, divided by the cosine of the latitude, in a transverse Mercator.", "The longitude difference from the central meridian, times the sine of the latitude.", "The angle subtended at the pole by the arc from the central meridian to the point, measured along the parallel."]'::jsonb, 2, 'So it is zero on the central meridian, grows away from it, and grows with latitude.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 12, 'How large can convergence get in a standard UTM zone?', '["Never more than half a degree.", "Up to six degrees, which is the width of the zone and therefore the maximum meridian separation within it.", "It is unbounded near the poles, which is why UTM is not used above 84 degrees of latitude.", "About 2.6 degrees at 60 degrees latitude, at the edge of the zone."]'::jsonb, 3, 'A zone is six degrees wide, so the maximum offset from the central meridian is three degrees. At the equator convergence is zero regardless of longitude.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 13, 'What shape of error does an azimuth reference error produce?', '["A rigid rotation of the whole well path about the vertical axis where it entered.", "A random scatter about the true path.", "A growing random walk, since the error enters at every station and accumulates down the well from there.", "A vertical shift, since the reference error changes the datum the azimuths are measured against."]'::jsonb, 0, 'It is not a scatter and it is not a walk. Every point below the entry moves by the same angle about the same axis.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 14, 'How far does one degree of azimuth reference error displace a point at 3000 m of reach?', '["About 5 m.", "About 52 m.", "About 105 m, since the displacement is measured across the full diameter of the rotation rather than the radius.", "It depends on the inclination, because a rotation about the vertical axis moves a steep well less than a flat one."]'::jsonb, 1, 'The displacement is the horizontal distance times the angle in radians. At 1000 m it is 17 m and at 6000 m it is 105 m.'),
  ('welldesign', 'advanced', 'module', 'm04-the-reference-frame', 15, 'Why is an azimuth reference error especially dangerous?', '["Because it grows with depth.", "Because it is a global source, so it affects every well in the field identically and cancels in a relative comparison.", "Because it moves the position laterally, which is the direction anti-collision cares about most.", "Because it changes the true vertical depth, which is what casing points and pressure calculations are quoted in."]'::jsonb, 2, 'It also exceeds the whole uncertainty budget at 3000 m of reach, and the error model does not cover it because the model covers residual uncertainty after a correct correction.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 1, 'What does a traveling cylinder plot show?', '["Separation factor against measured depth.", "The hole''s cross section at each station, with the drill string''s position inside it drawn to scale.", "Where the offset well is, in bearing and distance, seen from the reference well.", "The two wells'' trajectories projected onto a vertical plane containing both of their surface locations."]'::jsonb, 2, 'It is a polar plot centred on the reference well, with the angle measured from highside and the radius the distance to the offset.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 2, 'Which piece of information is missing from a separation factor alone?', '["Direction, which is what a directional driller needs in order to steer away.", "The minimum separation factor.", "The depth at which the closest approach occurs, which the ladder plot leaves to be read off the horizontal axis.", "The two hole radii, which are drawn to scale and show how much of the gap is geometry rather than uncertainty."]'::jsonb, 0, 'It also shows approach geometry and every neighbour at once, which is how a congested platform section is actually looked at.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 3, 'A neighbour stays at the same bearing while the distance shrinks. What is happening?', '["The two wells are crossing.", "A parallel well is closing in.", "The reference well is rotating about its own axis, which changes the highside reference the bearing is measured from.", "The offset well is being approached at its closest approach point, which is where the bearing stabilises."]'::jsonb, 1, 'One that sweeps around the plot is crossing. Two very different situations that can have similar minimum factors.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 4, 'What is a ladder plot?', '["A polar plot of the offset''s bearing.", "The two wells'' separation in three dimensions, drawn as rungs connecting the closest points on each trajectory.", "The centre-to-centre distance against depth, before the hole radii and the tool allowance are deducted.", "Separation factor against the reference well''s measured depth, with thresholds drawn."]'::jsonb, 3, 'The no-go and review lines are drawn horizontally, which is what makes the plot readable at a glance.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 5, 'Why read the whole ladder curve rather than the minimum?', '["Because the minimum may be at a station.", "Because the minimum is computed at stations and the true minimum lies between them, so the curve bounds the error.", "Because a brief excursion and a long stretch in the review band need different responses.", "Because the thresholds vary with depth, so a factor that clears at one depth may not clear at another."]'::jsonb, 2, 'Both can have the same minimum. Hundreds of metres drilled with reduced margin is a different problem from one point to manage.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 6, 'What does a sharp V in a ladder plot indicate?', '["A crossing, brief and well defined, with the minimum at the crossing depth.", "A survey gap in the offset well.", "A parallel approach, since the two wells run alongside each other over a short interval before separating again.", "A shared kickoff, where the two wells'' uncertainties stop being common and the factor drops sharply."]'::jsonb, 0, 'It tells you where the surveys need to be dense, which is a different action from what a long shallow trough asks for.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 7, 'How does this implementation compare against the published clearance oracle?', '["All eleven agree at machine precision.", "Ten of eleven agree at machine precision; the eleventh differs at far-field stations only.", "Ten agree and the eleventh disagrees on its minimum, which is why that case is excluded from the validation.", "All eleven agree to about one percent, which is the tolerance the standard states for conformance."]'::jsonb, 1, 'The eleventh is the only case with a kickoff, and it agrees exactly on its minimum and on its centre-to-centre distances.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 8, 'Where is the kicked-off case''s disagreement?', '["At the minimum separation factor.", "In the shallow section above the kickoff, where the two wells share the same hole and the sharing logic applies.", "In the centre-to-centre distances, which differ because the two implementations find different closest approaches.", "In the far field, where the two wells are widely separated and the factor is above twenty."]'::jsonb, 3, 'The largest instance is a factor of about 20.35 against an oracle value of about 20.21, which is under one percent.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 9, 'What has the kicked-off disagreement been ruled out as?', '["A defect in the published oracle.", "A difference in the confidence factor, since the two implementations use the same published value of 3.5.", "A geometry difference and an error model difference, both of which are validated separately.", "A rounding difference, since both implementations carry the same double precision throughout the calculation."]'::jsonb, 2, 'The centre-to-centre distances agree to machine precision, so both find the same closest approach on the same arcs.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 10, 'Why does the disagreement matter less than its size suggests?', '["Because it is at factors above twenty, where no decision is carried.", "Because it is under one percent.", "Because the oracle''s own values at far-field stations are published to fewer significant figures than the minimum.", "Because the far field is above the review threshold, and the standard does not require reporting above it."]'::jsonb, 0, 'A one percent difference at the no-go line would matter. At a factor above twenty nothing turns on it, and the minimum agrees exactly.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 11, 'Why does the course state what it will not certify?', '["Because the standard requires a scope statement.", "Because teaching a topic and certifying it are different claims about the learner.", "Because the engine would otherwise be used for calculations it cannot perform, which is a liability question.", "Because the go-live migration lists the topics and the course must match it for the migration to run."]'::jsonb, 1, 'The go-live migration asserts the separation the other way round: it refuses to run if any graded field key names one of the excluded topics.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 12, 'Why is gyroscopic surveying not certified here?', '["Because gyros are rarely used.", "Because gyro uncertainty can be obtained by scaling the magnetic result, so a separate model is not needed.", "Because the engine implements the magnetic error model and not the gyroscopic ones.", "Because gyro runs are made inside casing, where the anti-collision problem does not arise."]'::jsonb, 2, 'Gyros are used inside casing, through congested shallow sections, at high latitude, and wherever a critical section needs better than magnetic accuracy.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 13, 'What does the engine have instead of multi-station analysis?', '["A full implementation of the analysis.", "An in-field reference ingestion path, which achieves the same reduction by a different route.", "A correction applied automatically wherever the axial magnetic term exceeds a threshold share of the total.", "The ability to run with a different parameter set."]'::jsonb, 3, 'What it lacks is the analysis itself: taking a run of surveys and solving for the interference terms that best explain them.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 14, 'What does a complete anti-collision report need?', '["The traveling cylinder, the ladder, and the violation list.", "The minimum separation factor alone.", "The ladder plot and the minimum separation factor, since direction is a steering concern rather than a reporting one.", "The two wells'' covariances at every station, from which any reader can reconstruct the factors independently."]'::jsonb, 0, 'Direction, exposure, and the specific stations where a threshold is breached answer three different questions.'),
  ('welldesign', 'advanced', 'module', 'm05-reporting-and-its-limits', 15, 'Relief well ranging uses the same geometry. Why is it not certified?', '["Because relief wells are rare.", "Because ranging is an active measurement problem, not a passive geometric one.", "Because the mathematics runs in reverse, and the engine''s closest-approach solver only minimises distance rather than maximising it.", "Because relief wells are drilled under regulatory direction, which supersedes any engineering calculation."]'::jsonb, 1, 'It is named in the course because the geometry is the same, and it is graded nowhere because the engine does not do the measurement.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 1, 'At the end of the Expert modules, which judgement are you certified in?', '["Compute a well''s position uncertainty.", "Correct a magnetic survey for axial interference, using a run of stations covering a range of attitudes.", "Judge whether two wells are far enough apart, and say what every term in that judgement is.", "Design a trajectory that clears every offset well in a field, given the offsets'' surveys and their headers."]'::jsonb, 2, 'Designing to clear is the application. What this tier certifies is the judgement and the modelling choices inside it.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 2, 'In one sentence, what is the claim of this tier?', '["Two wells are safely apart when their surface clearance exceeds their combined uncertainty at an agreed confidence.", "Two wells are safe above a factor of 1.5.", "Two wells are safely apart when their centre-to-centre distance exceeds the sum of their two uncertainty ellipsoids.", "Two wells are safely apart when neither one''s ellipse, at the standard confidence, contains any part of the other."]'::jsonb, 0, 'Every term in that sentence is a modelling choice with a number attached, and the tier is about which numbers and who chose them.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 3, 'Of the eleven standard cases, how do they fall against the thresholds?', '["All eleven clear the review threshold.", "Two clear, four in review, five below the no-go line.", "Five clear, four in review, and two below the no-go line, which is why the set exercises the whole range.", "Nine clear and two in review; the set was chosen to be safe so that the arithmetic could be checked without alarm."]'::jsonb, 1, 'The set was chosen to exercise the decision space as well as the geometry, which is why so many of them fail.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 4, 'Why is the pedal-curve difference in the unsafe direction?', '["Because it always gives a larger factor.", "Because the radial method uses the semi-minor axis, which understates the extent of the ellipse in every direction.", "Because the pedal radius is measured to a tangent line, which lies outside the ellipse and is therefore conservative.", "Because the radial distance is smaller than the pedal radius for a tilted elongated ellipse."]'::jsonb, 3, 'Using the radial distance understates the uncertainty and overstates the separation factor, which is the direction that gets wells drilled.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 5, 'Which single number, chosen by convention, scales every positive separation factor?', '["The surface position sigma, at 0.5 m.", "The tool projection allowance, at 0.3 m, which is subtracted from every centre-to-centre distance before dividing.", "The confidence factor k, at 3.5 in the standard.", "The no-go threshold of 1.0, against which every computed factor is compared before a plan is accepted."]'::jsonb, 2, 'Halving it doubles the factor. That is why it must be agreed in advance and not adjusted after the answer is seen.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 6, 'Where does the survey error model contribute almost nothing?', '["In the shallow section, where the surface position term dominates.", "At total depth on a long horizontal.", "Above the kickoff of a sidetrack, where the two wells share the same hole and no relative uncertainty exists.", "Wherever the two wells are parallel, since a parallel geometry cancels the lateral component of both ellipses."]'::jsonb, 0, 'That is exactly where platform wells are closest, so the hardest part of the problem is decided by wellhead positions rather than surveys.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 7, 'Which of the added terms is geometry rather than statistics?', '["The surface position sigma.", "The tool projection allowance and the two hole radii.", "The confidence factor, since it is a fixed multiplier rather than a quantity estimated from any data.", "The combined sigma, which is a deterministic projection of two known covariances onto a known direction."]'::jsonb, 1, 'They are subtracted from the distance. The surface sigma is added to the uncertainty, which makes it statistics.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 8, 'What is the size of a one degree azimuth reference error at 3000 m of reach?', '["About 5 m, which is within the ellipse.", "About 26 m, which is the model''s own stated declination uncertainty expressed as a position at that reach.", "It depends on the confidence factor, since the error is expressed as an addition to the combined sigma.", "About 52 m, larger than the whole uncertainty budget and outside the model entirely."]'::jsonb, 3, 'Half the model''s stated declination uncertainty is 26 m at that reach, which is a different quantity and a useful comparison.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 9, 'What is checked against its publisher''s own test values in this tier?', '["The survey error model''s weighting functions.", "The closest-approach solver, against the published centre-to-centre distances of the eleven standard cases.", "The geomagnetic model, at twelve published points.", "The pedal-curve projection, against a set of ellipses and directions the standard publishes for that purpose."]'::jsonb, 2, 'It agrees to the precision the publisher prints, which is what makes the declination in a capstone field a reproducible quantity.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 10, 'What does the capstone ask you for?', '["Three separation factors, one of them at a raised confidence, and two geomagnetic quantities.", "Six separation factors from the standard set.", "The six numbers the professional tier computed, recomputed with the clearance parameter set rather than the survey one.", "A complete anti-collision report for the reference well, with a ladder plot and a violation list at every station."]'::jsonb, 0, 'The raised-confidence field is the one that demonstrates the scale break, because the case it is computed on is negative.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 11, 'Why does raising k improve a negative separation factor?', '["Because a larger k widens the clearance.", "Because the numerator is fixed and negative, so a larger denominator moves the ratio toward zero.", "Because the pedal radius grows faster than linearly in k, so the factor approaches zero from below asymptotically.", "Because the two wells'' shared uncertainty is removed at higher confidence, which reduces the combined sigma."]'::jsonb, 1, 'Choosing a wider confidence interval improves the number without moving either well, which is where the scale stops meaning anything.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 12, 'What are the four things this course teaches and does not certify?', '["Nothing: everything taught is certified.", "Trajectory design, torque and drag, hydraulics, and casing wear, which belong to the other courses in the module.", "The survey error model, the clearance calculation, the geomagnetic model, and the closest-approach solver.", "Gyroscopic models, multi-station analysis and in-field referencing, relief well ranging, and probabilistic risk."]'::jsonb, 3, 'The go-live migration refuses to run if any graded field key names one of them, which turns the scope statement into an assertion.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 13, 'What is the first habit this tier asks you to carry?', '["Always use the radial distance.", "Always compute the separation factor at every station rather than only at the closest approach between the two wells.", "Put both wells in one frame before computing anything.", "Always raise the confidence factor when a plan is marginal, since the higher value is the conservative choice."]'::jsonb, 2, 'The calculation runs perfectly on two wells that are not where it thinks they are, and nothing in the output reveals it.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 14, 'What is the second habit?', '["Agree the confidence factor before you see the answer.", "Report only the minimum separation factor.", "Exclude plugged and abandoned wells from the scan, since they carry no pressure and cannot flow if intersected.", "Use the published parameter set for every offset well, since an operator''s own set is not comparable with it."]'::jsonb, 0, 'The factor is a lever with a large effect, and adjusting it afterwards converts a safety criterion into a formality.'),
  ('welldesign', 'advanced', 'module', 'm06-the-expert-reading', 15, 'Stripped of jargon, what kind of quantity is it?', '["A calculated probability of collision.", "A dimensionless number whose every term is a modelling choice, compared against a consensus threshold.", "A measured distance between two wellbores, expressed as a multiple of the survey tools'' stated accuracy.", "The regulator''s criterion for whether a well may be drilled, which is why the thresholds are fixed by statute."]'::jsonb, 1, 'Calling it a probability is the overstatement that the thresholds'' margin above 1.0 exists to protect against.'),
  ('welldesign', 'advanced', 'final', null, 1, 'A planner runs a scan against every well within 100 m of the plan and reports all clear. What is your concern?', '["The scan should use 50 m instead.", "The radius is a choice, and a well just outside it is not in the scan and raises no warning.", "A hundred metres is too wide, so the scan will report many nuisance violations that mask the real ones.", "The radius should be measured in three dimensions rather than horizontally, which is what the standard specifies."]'::jsonb, 1, 'The scan is only as complete as the list it was given, and its absences are silent.'),
  ('welldesign', 'advanced', 'final', null, 2, 'An old well''s survey exists only on paper and was never digitised. What does your scan say about it?', '["Nothing at all, and that is the most dangerous case in the module.", "It flags it as an unknown offset.", "It includes it with a default parameter set, since an undigitised survey still has a recorded surface location.", "It reports a conservative separation factor based on the well''s total depth and surface position alone."]'::jsonb, 0, 'Fields drilled before digital records have wells whose surveys exist on paper or not at all, and a scan produces no warning for them.'),
  ('welldesign', 'advanced', 'final', null, 3, 'Two operators share a field boundary. What does clearing against their wells require?', '["A larger search radius.", "A conservative assumption about their well positions, since a field boundary is a regulated separation.", "Their data, obtained through a commercial and legal process as well as a technical one.", "Nothing: a field boundary is a barrier and wells on either side of it cannot come into conflict."]'::jsonb, 2, 'A field boundary is not a barrier, and it is one of the recurring sources of wells that are physically there and not in anybody''s scan.'),
  ('welldesign', 'advanced', 'final', null, 4, 'A sidetrack is recorded in the database as part of its parent well. What has been lost?', '["The sidetrack''s own survey.", "The kickoff depth, which is what the shared-uncertainty logic requires in order to remove the common part.", "The parent well''s total depth, since the record now ends at the deepest point of the sidetrack instead.", "The abandoned original legs, which are physically there and not in the record."]'::jsonb, 3, 'A well with several sidetracks may be one entity with one survey, and every abandoned leg is a hole with steel in it.'),
  ('welldesign', 'advanced', 'final', null, 5, 'Your scan takes the nearest offset station at each reference station. What is the error?', '["It underestimates the separation.", "It overestimates the separation, because the true closest point lies between stations.", "It is exact whenever the two wells have the same survey interval, which is the usual case on a platform.", "It is exact for parallel wells and wrong only where the two trajectories cross at a significant angle."]'::jsonb, 1, 'On a thirty metre interval with two wells crossing at an angle the overestimate can be metres, and metres is the whole margin.'),
  ('welldesign', 'advanced', 'final', null, 6, 'Why is the closest-approach solution written in closed form?', '["Because a scan runs it tens of thousands of times and a planner adjusts trajectories interactively.", "Because iteration is less accurate.", "Because the arcs are not differentiable at their joins, so no gradient-based search can be used on them.", "Because a closed form gives a unique answer, whereas an iterative search can converge to a local minimum."]'::jsonb, 0, 'The local minimum point is real for a general curve and not for a single arc, on which the minimum is unique.'),
  ('welldesign', 'advanced', 'final', null, 7, 'Two wells are 3 m apart at their closest approach near surface. How much of that is clearance?', '["All 3 m, before uncertainty.", "About 2.5 m, since the tool projection allowance applies only below the last casing shoe of the reference well.", "Under 2 m, once two hole radii and the tool projection allowance are deducted.", "It cannot be said without the confidence factor, since the deductions are scaled by it along with the uncertainty."]'::jsonb, 2, 'In the standard example those three sum to 1.062 m. The deductions are geometry and they are not scaled by k.'),
  ('welldesign', 'advanced', 'final', null, 8, 'A colleague argues the hole radius should be the bit size. What do you say?', '["The bit size is correct by definition.", "The radius should be the casing outside diameter, since the casing is what an intersecting bit would actually contact.", "The radius should be the drill pipe diameter, since the steel in the hole is what a collision would strike.", "A reamed or washed-out hole is larger, and the radius is an input for that reason."]'::jsonb, 3, 'The standard examples use section-size values rather than universal constants, which is the same point made another way.'),
  ('welldesign', 'advanced', 'final', null, 9, 'A scan combines two wells whose surveys are each relative to their own wellhead, without adding the offsets. What do you see?', '["Factors that are far too large.", "No change, since the separation factor depends only on relative geometry and both wells share the same origin.", "Separation factors that are far too small, which at least gets noticed.", "A vertical shift between the two wells, which shows as a constant offset in the ladder plot at every depth."]'::jsonb, 2, 'The reverse error, adding an offset that was already applied, makes the wells look far apart and does not get noticed.'),
  ('welldesign', 'advanced', 'final', null, 10, 'One well is grid-referenced and the other true-referenced, at a location with 1.5 degrees of convergence. What is the position error at 3000 m?', '["About 78 m, since one degree at that reach is about 52 m.", "About 1.5 m, one metre per degree.", "About 26 m, which is the model''s stated declination uncertainty at that reach expressed as a position.", "None, since convergence affects the map projection rather than the physical position of either well."]'::jsonb, 0, 'The displacement is the horizontal distance times the angle in radians, so it scales linearly with both.'),
  ('welldesign', 'advanced', 'final', null, 11, 'A jack-up and a platform drill from the same location. What must you check before scanning?', '["Their hole radii and tool allowances.", "Their depth datums, since the rig floor elevations differ.", "Their confidence factors, since two rigs operated by different contractors may use different anti-collision procedures.", "Their survey intervals, since the scan pairs stations and needs both lists sampled at matching depths."]'::jsonb, 1, 'One well ends up systematically shifted vertically relative to the other, and the scan reports it as a real separation.'),
  ('welldesign', 'advanced', 'final', null, 12, 'You are asked to justify the pedal-curve method to a reviewer. What is the argument?', '["It is the industry convention.", "It gives a larger uncertainty, so it is the conservative choice whichever geometry the two wells present.", "It is invariant under rotation of the frame, whereas the radial distance depends on the axes chosen.", "The question is how far the ellipse can extend towards the other well, not along the line to it."]'::jsonb, 3, 'For a tilted elongated ellipse the two answers differ, and the radial one understates the uncertainty in exactly the wrong direction.'),
  ('welldesign', 'advanced', 'final', null, 13, 'A separation factor of 1.2 is reported. What happens next?', '["The well is drilled as planned.", "The plan is rejected, since only factors above the review threshold of 1.5 are acceptable at any confidence.", "Review: additional mitigation, a revised plan, or an explicit management decision.", "The confidence factor is recomputed at 2.0, which is the documented remedy for a marginal plan."]'::jsonb, 2, 'Between 1.0 and 1.5 the plan is neither clear nor refused. Adjusting k to clear it is what module 3 says must not happen.'),
  ('welldesign', 'advanced', 'final', null, 14, 'Why does the industry not treat 1.0 as the safe line?', '["Because the model excludes gross errors, old wells'' real parameters, and its own tails.", "Because 1.0 is a rounding of 1.06.", "Because a factor of exactly 1.0 means the two centrelines coincide, which is a certain collision rather than a margin.", "Because the separation factor is computed at stations, and the true minimum between stations can be lower."]'::jsonb, 0, 'A factor of 1 means the ellipses touch at k of 3.5, which sounds like a wide margin and is a scaling of an approximate model.'),
  ('welldesign', 'advanced', 'final', null, 15, 'A plan clears at k of 2.0 and fails at 3.5. Which is the answer?', '["The one at 2.0, since it clears.", "The one at the confidence factor agreed before the calculation was run.", "Neither: a plan whose verdict depends on the confidence factor should be redesigned until it clears at both.", "The one at 3.5, since a higher confidence factor is always the more conservative and therefore the correct choice."]'::jsonb, 1, 'Redesigning until it clears at both is good practice and it is not what makes one number the answer. The agreement in advance is.'),
  ('welldesign', 'advanced', 'final', null, 16, 'At 100 m below the mudline, what dominates the combined uncertainty?', '["The axial magnetic interference term.", "The depth-only sources, which are systematic and therefore present from the first station of the survey.", "The tool projection allowance, which is a fixed 0.3 m and exceeds everything else at that depth.", "The surface position term, because survey uncertainty starts at zero and grows."]'::jsonb, 3, 'The allowance is a geometric deduction rather than an uncertainty. At that depth a well''s survey uncertainty is centimetres against half a metre of surface term.'),
  ('welldesign', 'advanced', 'final', null, 17, 'An old well was positioned by triangulation from a shoreline. What surface sigma would you use?', '["Half a metre, the standard value.", "Centimetres, since a shoreline triangulation is a geodetic survey and those are accurate to the instrument.", "Metres to tens of metres, far above the standard example''s half metre.", "It cannot be estimated, so the well should be excluded from the scan and handled by procedure instead."]'::jsonb, 2, 'Excluding it is the worst option available. The standard value is generous for a modern satellite fix and optimistic by an order of magnitude here.'),
  ('welldesign', 'advanced', 'final', null, 18, 'A reviewer asks what the 0.3 m is for. Name both physical effects.', '["The hole between the sensor and the bit, and the string lying off the hole centreline.", "Survey error and depth error.", "The distance the assembly can be pushed by a bent housing, and the amount the hole can wash out during drilling.", "The uncertainty of the last surveyed station, and the projection of the plan ahead of it to the next station."]'::jsonb, 0, 'The sensor sits ten to twenty metres behind the bit, and the string lies against the low side, is pushed by the housing, and buckles.'),
  ('welldesign', 'advanced', 'final', null, 19, 'A reviewer calls the tool projection allowance a safety margin. Correct them.', '["It is a safety margin at k of 3.5.", "It is a geometric correction: it says where the steel is, not how confident we are.", "It is a statistical term, added in quadrature with the two wells'' position uncertainties before scaling by k.", "It is both, since it covers a physical offset and an allowance for how far the assembly might have moved."]'::jsonb, 1, 'It is subtracted from the distance rather than added to the uncertainty, and that is the test of which kind of term it is.'),
  ('welldesign', 'advanced', 'final', null, 20, 'Two wells share a slot. What does adding their covariances in quadrature do?', '["It gives the correct combined uncertainty.", "It removes the shared part automatically, since a common error contributes equally to both and cancels in the difference.", "It has no effect on the minimum, which occurs below the kickoff where the two wells no longer share anything.", "It inflates the combined sigma and makes them look closer than they are."]'::jsonb, 3, 'If the wellhead is off by forty centimetres, both wells are off by forty centimetres and the gap between them is unchanged.'),
  ('welldesign', 'advanced', 'final', null, 21, 'Is treating shared uncertainty as independent dangerous?', '["Yes, it approves unsafe plans.", "Yes, because the inflated sigma pushes negative separation factors toward zero and makes them read as acceptable.", "No: it is pessimistic. It rejects safe plans rather than approving unsafe ones.", "It depends on the geometry: pessimistic for parallel wells and optimistic where the two wells cross."]'::jsonb, 2, 'It is still wrong, and the standard''s kicked-off case exists to exercise the logic that handles it correctly.'),
  ('welldesign', 'advanced', 'final', null, 22, 'Above which point do a parent and its sidetrack have nothing to disagree about?', '["The kickoff point, above which the two wells are the same hole.", "The last common casing shoe.", "The depth at which the two surveys'' positions first differ by more than the survey uncertainty at that station.", "The tie-on depth, which is where the sidetrack''s independent survey run begins to accumulate its own error."]'::jsonb, 0, 'There is one hole with one survey above it, so there is nothing there for the two wells to disagree about.'),
  ('welldesign', 'advanced', 'final', null, 23, 'How does declination differ from convergence in what it depends on?', '["They depend on the same things.", "Declination depends on position and time; convergence on position and projection only.", "Declination depends on the map projection and convergence on the geodetic datum, so both are cartographic.", "Declination depends on latitude alone and convergence on longitude alone, which is why they are independent."]'::jsonb, 1, 'That is why a survey header records a declination and a date, and records a convergence with no date at all.'),
  ('welldesign', 'advanced', 'final', null, 24, 'A survey header''s declination sign has been applied backwards. What do you see?', '["The model refuses to run.", "An inflated uncertainty, since the error model''s declination source will absorb the discrepancy into the covariance.", "A vertical error, since the azimuth reference affects the true vertical depth accumulation through the inclination.", "The whole well rotated by twice the declination, and nothing in the output showing it."]'::jsonb, 3, 'Both signs are conventions and both have been implemented backwards in real software. The check is a case with a known answer.'),
  ('welldesign', 'advanced', 'final', null, 25, 'A field is drilled in the last year of a model release. What has got worse?', '["Because the coefficients are truncated.", "Because the model omits the crustal field, whose relative contribution grows as the main field weakens over the period.", "Because the secular variation term is linear and the field''s drift is not.", "Because fewer observatories contribute to the model as the period progresses and stations are decommissioned."]'::jsonb, 2, 'That is why the release cycle is five years and why the evaluation date is part of the input rather than an afterthought.'),
  ('welldesign', 'advanced', 'final', null, 26, 'Half a degree of declination error at 3000 m of reach is how much position?', '["About 26 m.", "About 3 m.", "About 52 m, since one degree is 26 m and the relationship between angle and displacement is quadratic.", "It depends on the inclination, because a rotation about the vertical moves a steep well less than a flat one."]'::jsonb, 0, 'One degree at that reach is about 52 m, so half a degree is half of it. That figure is the model''s own stated uncertainty at mid latitudes.'),
  ('welldesign', 'advanced', 'final', null, 27, 'A well is drilled at the edge of a UTM zone at 60 degrees latitude. How much convergence?', '["About 6 degrees, the zone width.", "About 2.6 degrees.", "Zero, because convergence vanishes at the zone edges and is largest on the central meridian.", "About 0.5 degrees, which is the model''s stated declination uncertainty and the same order of magnitude."]'::jsonb, 1, 'The maximum offset from the central meridian is three degrees, times the sine of the latitude, which at 60 degrees is about 0.87.'),
  ('welldesign', 'advanced', 'final', null, 28, 'Why is an azimuth reference error a rotation rather than a scatter?', '["Because the model treats it as global.", "Because it enters at the surface, where the well has no horizontal displacement and the error cannot yet scatter.", "Because a reference error affects only the azimuth column, which is a direction rather than a position.", "Because a constant angular offset applies to every station below where it entered."]'::jsonb, 3, 'Every point below the entry moves by the same angle about the same vertical axis, which is exactly a rigid rotation.'),
  ('welldesign', 'advanced', 'final', null, 29, 'Why does an azimuth reference error land in the worst possible direction?', '["Because it is proportional to depth.", "Because it accumulates systematically, so a hundred stations give a hundred times one station''s contribution.", "Because the displacement is perpendicular to travel, which is the lateral component.", "Because it moves the true vertical depth, which is the component a casing point and a pressure test both depend on."]'::jsonb, 2, 'Lateral is already the largest component of the ellipse and it is the one anti-collision cares about most.'),
  ('welldesign', 'advanced', 'final', null, 30, 'A neighbour sweeps around the traveling cylinder plot as you drill. What is the geometry?', '["A crossing.", "A parallel well closing in.", "A shared kickoff, where the two wells separate and the bearing rotates as the sidetrack turns away from the parent.", "A well that is being approached along its own axis, so its bearing appears to rotate as the reference passes it."]'::jsonb, 0, 'One that stays at the same bearing while the distance shrinks is a parallel well closing in. Similar minima, very different situations.'),
  ('welldesign', 'advanced', 'final', null, 31, 'Two plans have the same minimum separation factor. One is a sharp V, the other a long shallow trough. Are they equally acceptable?', '["Yes, the minimum is the criterion.", "No: a brief excursion is a point to manage, and hundreds of metres in the review band is not.", "No: the sharp V is worse, because a crossing carries a collision risk that a parallel approach does not.", "It cannot be judged without the traveling cylinder, since the ladder plot does not show the approach direction."]'::jsonb, 1, 'The cylinder is genuinely needed for direction, and the ladder''s shape already distinguishes these two on exposure alone.'),
  ('welldesign', 'advanced', 'final', null, 32, 'This implementation differs from the oracle by under one percent on one case. Where?', '["At the minimum of every case.", "At the shallow stations above the kickoff, where the two wells share a hole and the sharing logic applies.", "In the centre-to-centre distances, which is why the separation factors differ at those stations.", "At far-field stations of the kicked-off case, at factors above twenty."]'::jsonb, 3, 'It agrees exactly on the minimum and on the centre-to-centre distances, so nothing that carries a decision is affected.'),
  ('welldesign', 'advanced', 'final', null, 33, 'Why is that disagreement worth stating rather than hiding?', '["Because the standard requires disclosure.", "Because it may indicate a defect that will grow into a material one as the implementation is extended.", "Because a reader who finds it independently should already know its size and where it is.", "Because the oracle may be wrong, and publishing the difference invites the maintaining group to check it."]'::jsonb, 2, 'Both of the other reasons are defensible and secondary. A validation claim that omits its own known exception is not a validation claim.'),
  ('welldesign', 'advanced', 'final', null, 34, 'A gyro run is proposed for the shallow congested section. What can this engine say about its uncertainty?', '["Nothing: it implements the magnetic model and not the gyroscopic ones.", "It can scale the magnetic result.", "It can run the magnetic model with the gyro parameter set, which is how gyro uncertainty is normally obtained.", "It can bound it, since a gyro is more accurate than a magnetic survey and the magnetic answer is therefore conservative."]'::jsonb, 0, 'Their error models exist and are published by the same body, with different sources and different propagation. A gyro run''s uncertainty cannot be obtained by scaling.'),
  ('welldesign', 'advanced', 'final', null, 35, 'The engine can run with a different parameter set. Is that multi-station analysis?', '["Yes, that is exactly what it is.", "No: the analysis is solving a run of surveys for the interference terms, which the engine does not do.", "No, but it is equivalent in effect, since a corrected parameter set is the output of a multi-station analysis.", "Yes for the magnetic sources, and no for the depth sources, which the analysis does not address."]'::jsonb, 1, 'A corrected parameter set is what a completed analysis would justify. Running with one is not performing it.'),
  ('welldesign', 'advanced', 'final', null, 36, 'What does the go-live migration assert about the excluded topics?', '["It records them in a documentation table.", "It removes the lessons that mention them, so the course content matches what the capstone actually grades.", "It sets a flag that hides the excluded topics from the course catalogue until an engine implements them.", "It refuses to run if any graded field key names one of them."]'::jsonb, 3, 'That turns a scope statement in prose into an assertion the database enforces, which is what makes it durable.'),
  ('welldesign', 'advanced', 'final', null, 37, 'A capstone field asks for a minimum separation factor at a raised confidence. Why?', '["Because 5.0 is the conservative choice.", "Because raising the confidence factor tests whether the implementation applies it to both wells rather than one.", "Because on a negative factor a wider interval improves the number without moving either well.", "Because the standard publishes values at both 3.5 and 5.0, so the pair can be checked against two oracles."]'::jsonb, 2, 'It is the demonstration that the scale stops meaning anything below zero, made as a graded number rather than a claim.'),
  ('welldesign', 'advanced', 'final', null, 38, 'You are handed a separation factor and asked whether the well is safe. What do you need alongside it?', '["The confidence factor, the parameter sets, the frame, and the list of offsets scanned.", "The two wells'' total depths.", "The minimum''s measured depth and the hole radii used, which are the only two inputs that vary between operators.", "The oracle values for the same pair, so that the implementation can be checked before the number is relied on."]'::jsonb, 0, 'Every one of those can change the answer, and none of them appears in the number itself.'),
  ('welldesign', 'advanced', 'final', null, 39, 'What is the strongest single argument for reading the whole ladder rather than the minimum?', '["The minimum may be computed wrongly.", "Exposure: length of hole drilled with reduced margin is a risk the minimum does not express.", "The minimum occurs between stations, so the plotted curve is the only place the true value can be read.", "The thresholds change with depth, so a factor must be compared against the line at its own depth."]'::jsonb, 1, 'More hole in the review band means more opportunities for the actual to diverge from the plan, with no single point to concentrate on.'),
  ('welldesign', 'advanced', 'final', null, 40, 'Why does calling the separation factor a probability overstate it?', '["Because probabilities cannot be negative.", "Because the underlying position distribution is not normal, so no factor maps to a probability at all.", "Because k is a chosen scaling of a model with unmodelled tails.", "Because the factor is a ratio of two lengths, and a ratio of lengths cannot be interpreted probabilistically."]'::jsonb, 2, 'The negativity point is a real symptom of the same thing. Gross errors, surface position, hole radius, and model error all sit outside what k scales.'),
  ('welldesign', 'advanced', 'final', null, 41, 'What is the one habit that most often prevents a wrong scan?', '["Using the pedal-curve method.", "Running the scan at several confidence factors, so that a marginal result is visible across the range.", "Reading the traveling cylinder as well as the ladder, so that direction is never inferred from magnitude alone.", "Putting both wells in one frame, with one origin, one north, and one datum."]'::jsonb, 3, 'The others are all worth doing. This is the one where the calculation runs perfectly and answers the wrong question.'),
  ('welldesign', 'advanced', 'final', null, 42, 'A colleague says an anti-collision scan is an engineering nicety. Respond.', '["It is a permit-to-drill item, because an intersection is a well control event with two wells involved.", "It is a regulatory formality only.", "It is a planning tool: once the well is being drilled, the surveys supersede the scan and the plan is no longer relevant.", "It is a nicety above a factor of 1.5, and a requirement only where the plan enters the review band."]'::jsonb, 0, 'If the offset is a producer its pressure is in your annulus with no barrier, and the standard outcome is losing both wells.');
